/* getInventories devolve uma LISTA de catálogos, não um objeto indexado pelo
   id — o fluxo antigo já dizia isso em `inventories[0].inventory_id`. Ler com
   Object.entries devolvia a CHAVE do array, que é "0", e a Base respondia
   "Storage with specified identifier does not exist". As duas formas são
   aceitas aqui porque não custa nada e evita a próxima surpresa. */
function _catalogos(resp) {
  const inv = (resp && resp.inventories) || [];
  if (Array.isArray(inv)) {
    return inv.map(x => ({ id: String(x.inventory_id), nome: x.name || '' }));
  }
  return Object.entries(inv).map(([k, v]) => ({
    id: String((v && v.inventory_id) || k),
    nome: (v && v.name) || ''
  }));
}
/* Mesma história com os armazéns: lista na documentação, mas defensivo. A
   chave que aparece no estoque do produto é tipo + "_" + id ("bl_43152"). */
function _armazens(resp) {
  const w = (resp && resp.warehouses) || [];
  const arr = Array.isArray(w) ? w : Object.values(w);
  return arr.map(x => ({
    chave: String(x.warehouse_type || '') + '_' + String(x.warehouse_id || ''),
    nome: x.name || (String(x.warehouse_type || '') + '_' + String(x.warehouse_id || ''))
  }));
}

const est = $getWorkflowStaticData('global');
est.pagina = 1;
est.gravados = 0;
est.semCampoCusto = 0;
est.chavesSemNome = [];

const cat = $('Base · catálogos').first().json || {};
if (cat.status !== 'SUCCESS') {
  throw new Error('Não consegui listar os catálogos: ' + (cat.error_message || JSON.stringify(cat).slice(0, 300)));
}
const catalogos = _catalogos(cat);
if (!catalogos.length) throw new Error('A Base não devolveu nenhum catálogo.');

/* Um catálogo só. Se um dia houver mais de um, o log diz qual foi lido em
   vez de escolher em silêncio. */
const escolhido = catalogos[0];

const arm = $('Base · armazéns').first().json || {};
const mapa = {};
_armazens(arm).forEach(a => { mapa[a.chave] = a.nome; });

console.log('catálogo: ' + escolhido.id + ' · ' + (escolhido.nome || '(sem nome)')
  + ' | catálogos disponíveis: ' + catalogos.length
  + ' | armazéns: ' + Object.keys(mapa).length + ' → ' + Object.values(mapa).join(', '));

/* ── OS CAMPOS DA FICHA DO PRODUTO (01/09/2026) ──────────────────────
   Peso e medidas vêm prontos no produto. NCM, Duração e Preço Site não:
   na Base eles são "campo adicional" e "grupo de preço", cada um com um id
   numérico próprio da conta. Chutar id daria o campo errado calado — o pior
   tipo de erro, porque parece que funcionou.

   Então o fluxo PERGUNTA à Base quais existem e casa pelo NOME. Se um dia o
   nome mudar lá, o log diz que não achou e o LiveOps mostra "não informado",
   em vez de exibir o número de outro campo. */
function _chave(s) {
  return String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/\s+/g, ' ').trim();
}

const ex = $('Base · campos extras').first().json || {};
const mapaExtras = {};
if (ex.status === 'SUCCESS') {
  const lista = Array.isArray(ex.extra_fields) ? ex.extra_fields : Object.values(ex.extra_fields || {});
  lista.forEach(f => {
    const id = f && (f.extra_field_id !== undefined ? f.extra_field_id : f.id);
    if (id === undefined) return;
    mapaExtras[_chave(f.name)] = 'extra_field_' + id;
  });
} else {
  console.log('AVISO: não consegui listar os campos adicionais — NCM e Duração vão em branco. '
    + (ex.error_message || ''));
}

const gp = $('Base · grupos de preço').first().json || {};
let precoSiteId = null;
if (gp.status === 'SUCCESS') {
  const lista = Array.isArray(gp.price_groups) ? gp.price_groups : Object.values(gp.price_groups || {});
  /* Nome exato primeiro; "contém site" só como segunda chance, para
     aguentar "Preço Site (BRL)" sem aceitar qualquer coisa. */
  const exato = lista.find(g => _chave(g.name) === 'preco site');
  const perto = lista.find(g => _chave(g.name).indexOf('site') >= 0);
  const alvo = exato || perto;
  if (alvo) precoSiteId = String(alvo.price_group_id);
  console.log('grupos de preço: ' + lista.map(g => g.name).join(', ')
    + ' | "Preço Site" = ' + (precoSiteId || 'NÃO ENCONTRADO'));
} else {
  console.log('AVISO: não consegui listar os grupos de preço — Preço Site vai em branco. '
    + (gp.error_message || ''));
}

const CAMPOS_FICHA = { ncm: 'ncm', duracao: 'duracao' };
const idsFicha = {};
Object.keys(CAMPOS_FICHA).forEach(k => {
  const achado = mapaExtras[_chave(CAMPOS_FICHA[k])];
  if (achado) idsFicha[k] = achado;
});
console.log('campos adicionais achados: '
  + (Object.keys(idsFicha).length ? Object.keys(idsFicha).join(', ') : 'nenhum')
  + ' | disponíveis na Base: ' + Object.keys(mapaExtras).join(', '));

return [{ json: { inventory_id: escolhido.id, mapaArmazens: mapa,
  idsFicha: idsFicha, precoSiteId: precoSiteId, pagina: 1 } }];

/* Ids da página. Página vazia encerra o laço devolvendo zero itens — o n8n
   não tem "pare aqui", quem para é a ausência de item. */
const r = $input.first().json || {};
if (r.status !== 'SUCCESS') {
  throw new Error('Página de produtos recusada pela Base: ' + (r.error_message || JSON.stringify(r).slice(0, 300)));
}
const ids = Object.keys(r.products || {});
const inicio = $('De onde começar').first().json;

if (!ids.length) {
  const est = $getWorkflowStaticData('global');
  console.log('fim da varredura — ' + est.gravados + ' produtos gravados em ' + (est.pagina - 1) + ' páginas'
    + (est.semCampoCusto ? (' | ATENÇÃO: average_cost ausente em ' + est.semCampoCusto + ' produtos — a Base pode ter mudado o campo') : '')
    + (est.chavesSemNome.length ? (' | armazéns sem nome no mapa: ' + est.chavesSemNome.join(', ')) : ''));
  return [];
}

return [{ json: { ids, inventory_id: inicio.inventory_id } }];

/* Um registro por produto.

   O custo médio é o `average_cost` — confirmado contra a conta em
   23/08/2026. Antes daqui o código procurava entre cinco nomes plausíveis,
   porque a rede daqui não alcança a Base e eu não podia conferir. A busca
   sai agora, e não por elegância: ela decidia olhando **o primeiro produto
   da primeira página**, e se justo esse viesse sem custo, o catálogo inteiro
   era gravado com preço nulo. Nome certo e conhecido não se adivinha.

   O que fica no lugar é um contador: se o campo sumir da resposta da Base
   um dia, o log diz em quantos produtos ele faltou — em vez de zerar o valor
   do estoque em silêncio. */
const CAMPO_CUSTO = 'average_cost';
/* Peso e medidas vêm como número ou como texto com vírgula, dependendo de
   como foram digitados na Base. Ausente e zero são coisas diferentes: zero
   em peso é peso zero (e some do rateio do frete), ausente é não cadastrado.
   Por isso null, e não 0, quando não vier nada. */
function _n(v) {
  if (v === undefined || v === null || v === '') return null;
  const x = Number(String(v).replace(',', '.'));
  return isFinite(x) ? x : null;
}
function _extra(p, chave) {
  if (!chave) return '';
  const tf = p.text_fields || {};
  const v = tf[chave];
  return (v === undefined || v === null) ? '' : String(v);
}

const r = $input.first().json || {};
if (r.status !== 'SUCCESS') {
  throw new Error('Dados dos produtos recusados pela Base: ' + (r.error_message || JSON.stringify(r).slice(0, 300)));
}
const est = $getWorkflowStaticData('global');
const inicio = $('De onde começar').first().json;
const mapa = inicio.mapaArmazens || {};
const idsFicha = inicio.idsFicha || {};
const precoSiteId = inicio.precoSiteId || null;
const carimbo = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

const pagina = {};
Object.entries(r.products || {}).forEach(([id, p]) => {
  /* O estoque vem como { "bl_43152": 7, "bl_45090": 0 }. A ordem é a que a
     Base mandou; não reordeno porque a ordem dela agrupa por tipo. */
  const armazens = Object.entries(p.stock || {}).map(([chave, qtd]) => {
    if (!mapa[chave] && est.chavesSemNome.indexOf(chave) < 0) est.chavesSemNome.push(chave);
    return { nome: mapa[chave] || chave, qtd: Number(qtd) || 0 };
  });
  const total = armazens.reduce((a, x) => a + x.qtd, 0);

  /* Campo ausente e campo zerado são coisas diferentes. Ausente é a API ter
     mudado; zerado é o produto não ter custo cadastrado, o que é comum e
     legítimo. Só o primeiro é problema, e só ele é contado. */
  if (p[CAMPO_CUSTO] === undefined) est.semCampoCusto = (est.semCampoCusto || 0) + 1;
  const custo = Number(p[CAMPO_CUSTO]);

  pagina['prod_' + id] = {
    id: 'prod_' + id,
    sku: String(p.sku || ''),
    /* EAN é texto, sempre. Ele começa com zero e número come o zero:
       "0047469009496" viraria 47469009496 e não bate mais com a etiqueta. */
    ean: String(p.ean || ''),
    /* O nome fica em text_fields.name — conferido no dado real. */
    nome: String((p.text_fields && p.text_fields.name) || p.name || ''),
    total: total,
    armazens: armazens,
    precoMedio: (isFinite(custo) && custo > 0) ? custo : null,
    /* Sem link por enquanto. O endereço products_catalog.php#product:<id>
       foi deduzido do link de pedido e a Base responde 500 nele — chute em
       link vira erro na cara de quem clicou. Quando o formato certo for
       confirmado no painel, ele entra aqui. */
    link: '',

    /* ── Ficha do produto (01/09/2026) ──────────────────────────────
       Peso e medidas saem prontos do produto; NCM e Duração são campos
       adicionais e o Preço Site é um grupo de preço — os três chegam pelo
       id que "De onde começar" descobriu pelo nome. Faltando o id, o campo
       vai vazio e o LiveOps mostra "não informado". */
    peso:        _n(p.weight),
    altura:      _n(p.height),
    largura:     _n(p.width),
    comprimento: _n(p.length),
    ncm:         _extra(p, idsFicha.ncm),
    duracao:     _extra(p, idsFicha.duracao),
    precoSite:   precoSiteId ? _n((p.prices || {})[precoSiteId]) : null,

    sincronizadoEm: carimbo,
    _by: 'n8n'
  };
});

est.gravados += Object.keys(pagina).length;
est.pagina += 1;
console.log('página ' + (est.pagina - 1) + ': ' + Object.keys(pagina).length + ' produtos');

/* UM item só. O nó Code tem uma saída só — devolver [[a],[b]] é a forma de
   dois ramos e ela não existe aqui. Os dois caminhos saem da mesma saída:
   "Gravar a página" lê .pagina e "Pausa 1s" leva .proximaPagina de volta. */
return [{ json: {
  pagina: pagina,
  proximaPagina: est.pagina,
  inventory_id: inicio.inventory_id
} }];
